const rainSteps={ideal:[['暖湿气流受阻抬升','携带水汽的气流遇山地阻挡，沿迎风坡被迫上升。'],['膨胀与绝热冷却','随高度增加，周围气压降低，上升气流膨胀，温度下降。'],['达到露点，凝结成云','气流冷却至露点、达到饱和后，水汽凝结为云滴。凝结成云并不等于立即降雨。'],['降水粒子增长并降落','云滴碰并或冰晶增长，形成足够大的降水粒子，才可能降落到地面。'],['背风侧下沉增温','越山气流下沉、压缩并绝热增温，相对湿度降低，云可消散；一定条件下形成焚风及雨影。']],tianmu:[['夏季西南气流背景','原资料讨论夏季低层西南气流等特定天气条件下的降水过程。'],['气流从山地两侧绕行','低层气流受山地阻挡，从两侧绕行，在背风侧形成辐合。'],['坡面受热，暖空气上升','白天坡面吸收太阳辐射，近地面空气受热；在有利层结下产生热力上升。空气上升、膨胀冷却，达到饱和后可凝结成云。'],['积云发展与辐合抬升','山地绕流的动力作用与局地热力作用共同促使背风侧对流云发展。'],['背风侧局地对流降水','对流云进一步发展，降水粒子增长，可在背风侧产生局地降水。此过程不代表全年所有天气。']]};
