 function niceDomain(values){
  const lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||Math.max(Math.abs(lo)*.2,1),rawStep=(span*1.3)/4,pow=10**Math.floor(Math.log10(rawStep)),v=rawStep/pow;
  const step=(v<=1?1:v<=2?2:v<=2.5?2.5:v<=5?5:10)*pow;
  let min=Math.floor((lo-span*.12)/step)*step,max=Math.ceil((hi+span*.16)/step)*step;if(min===max)max=min+step;
  return{min,max,step};
 }
 function drawAllCharts(){qa('.tm-chart-canvas').forEach(canvas=>{if(!canvas.isConnected)return;const ds=canvas.dataset.datasets.split('|').map(id=>datasets[id]),w=Math.max(250,Math.floor(canvas.getBoundingClientRect().width||460));canvas.innerHTML=canvas.dataset.chartKind==='stacked'?stackedSVG(ds,w):lineSVG(ds[0],w)})}
 function lineSVG(d,W){
  if(global.TianmuDigitalFigures?.numericPlot)return global.TianmuDigitalFigures.numericPlot(d,W,state.samples[d.study_id]);
  const H=235,L=57,R=20,T=23,B=43,pts=d.points,alts=unique(pts.map(x=>x.altitude_m)).sort((a,b)=>a-b),{min,max,step}=niceDomain(pts.map(p=>p.value));
  const x=a=>L+(a-alts[0])/(alts.at(-1)-alts[0])*(W-L-R),y=v=>H-B-(v-min)/(max-min)*(H-T-B);
  const label=v=>format(v);
  let s=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="${esc(d.title)}随海拔变化，单位${esc(d.unit)}。选中${state.samples[d.study_id]}米真实样点。"><text x="4" y="13" fill="#63746a" font-size="11">${esc(d.unit)}</text>`;
  for(let v=min,i=0;v<=max+step*.01&&i<12;v+=step,i++)s+=`<path d="M${L} ${y(v)}H${W-R}" fill="none" stroke="#e5ebe2"/><text x="${L-9}" y="${y(v)+4}" text-anchor="end" fill="#63746a" font-size="11">${label(v)}</text>`;
  s+=`<path d="M${L} ${T}V${H-B}H${W-R}" fill="none" stroke="#b7c4b9"/>`;
  const ticks=W<330?alts.filter((a,i)=>i===0||i===2||i===alts.length-1):alts;
  ticks.forEach(a=>s+=`<text x="${x(a)}" y="${H-B+21}" text-anchor="middle" fill="#63746a" font-size="11">${a}</text>`);
  const selected=state.samples[d.study_id];s+=`<path d="M${x(selected)} ${T}V${H-B}" fill="none" stroke="#abc2ae" stroke-dasharray="3 5"/>`;
  const hs=pts[0].horizon?['A1','B']:[null];
  hs.forEach((h,j)=>{const arr=pts.filter(p=>!h||p.horizon===h),color=hs.length>1?['#34654f','#507e98'][j]:/precipitation|water/.test(d.dataset_id)?'#507e98':/^root_|ph/.test(d.dataset_id)?'#887050':'#34654f';
   s+=`<path d="${arr.map((p,i)=>(i?'L':'M')+x(p.altitude_m)+' '+y(p.value)).join(' ')}" stroke="${color}" fill="none" stroke-width="2.2" ${h==='B'?'stroke-dasharray="5 4"':''} stroke-linecap="round" stroke-linejoin="round"/>`;
   arr.forEach((p,i)=>{const sel=p.altitude_m===selected,cx=x(p.altitude_m),cy=y(p.value);s+=`<g data-point="${d.dataset_id}|${p.altitude_m}" role="button" tabindex="0" aria-label="${p.altitude_m}米 ${esc(d.title)} ${format(p.value)}${esc(d.unit)}${h?' '+h+'层':''}"><title>${p.altitude_m} m：${format(p.value)} ${esc(d.unit)}${h?' '+h+'层':''}</title><circle cx="${cx}" cy="${cy}" r="15" fill="transparent"/>${sel?`<circle cx="${cx}" cy="${cy}" r="7" fill="#fff" stroke="${color}" stroke-width="1.8"/>`:''}<circle cx="${cx}" cy="${cy}" r="${sel?3:4}" fill="${sel?color:'#fff'}" stroke="${color}" stroke-width="1.8"/></g>`;
    if(!h&&(sel||i===0||i===arr.length-1))s+=`<text x="${cx+(i===0?2:i===arr.length-1?-2:0)}" y="${cy-13}" text-anchor="${i===0?'start':i===arr.length-1?'end':'middle'}" font-size="11" fill="#425a4c">${format(p.value)}</text>`;
   });
  });
  return s+`<text x="${W-R}" y="${H-5}" text-anchor="end" fill="#63746a" font-size="11">海拔 / m</text></svg>`;
 }
 function stackedSVG(ds,W){if(global.TianmuDigitalFigures?.stackedPlot)return global.TianmuDigitalFigures.stackedPlot(ds,W,state.samples[ds[0].study_id]);const H=250,L=57,R=22,T=28,B=43,pts=ds[0].points,n=pts.length,pw=W-L-R,y=v=>H-B-v/110*(H-T-B),bw=Math.min(55,pw/n*.55);let s=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="土壤粒径组成原报告百分比，1500米三项合计99%，未归一化"><text x="4" y="14" font-size="11" fill="#63746a">比例 / %</text>`;
  for(let v=0;v<=100;v+=20)s+=`<path d="M${L} ${y(v)}H${W-R}" stroke="#e5ebe2"/><text x="${L-9}" y="${y(v)+4}" text-anchor="end" fill="#63746a" font-size="11">${v}</text>`;
  pts.forEach((p,i)=>{let base=0;const x=L+pw*(i+.5)/n;ds.forEach((d,j)=>{const v=d.points[i].value;s+=`<rect x="${x-bw/2}" y="${y(base+v)}" width="${bw}" height="${v/110*(H-T-B)}" fill="${['#c39358','#d8c6a6','#6b9879'][j]}"><title>${p.altitude_m} m ${esc(d.title)} ${format(v)}%</title></rect>`;base+=v});s+=`<g data-point="${ds[0].dataset_id}|${p.altitude_m}" role="button" tabindex="0" aria-label="选择${p.altitude_m}米粒径样点"><rect x="${x-bw/2-4}" y="${y(base)-3}" width="${bw+8}" height="${H-B-y(base)+6}" fill="transparent" stroke="${state.samples[ds[0].study_id]===p.altitude_m?'#34654f':'none'}" stroke-width="1.5" rx="3"/></g><text x="${x}" y="${y(base)-10}" text-anchor="middle" font-size="11" fill="#425a4c">${format(base)}%</text><text x="${x}" y="${H-B+21}" text-anchor="middle" font-size="11" fill="#63746a">${p.altitude_m}</text>`});
  return s+`<text x="${W-R}" y="${H-5}" text-anchor="end" font-size="11" fill="#63746a">海拔 / m</text></svg>`;
 }
